class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers = {}  # name -> vip flag
        self._tickets = {}    # id -> dict with all info
        self._next_id = 1
        self._queue = []      # list of tuples for ordering

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = bool(vip)

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if priority not in self.PRIORITIES:
            raise ValueError(f"Unknown priority: {priority!r}")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer!r}")
        tid = self._next_id
        self._next_id += 1
        self._tickets[tid] = {
            "id": tid,
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
            "seq": tid,
        }
        self._enqueue(tid)
        return tid

    def _enqueue(self, ticket_id: int) -> None:
        t = self._tickets[ticket_id]
        vip = 0 if self._customers[t["customer"]] else 1
        # Lower tuple sorts first. VIP (0) beats non-VIP (1).
        # Higher priority sorts first -> negative index.
        prio = -self.PRIORITIES.index(t["priority"])
        self._queue.append((vip, prio, t["seq"], ticket_id))
        self._queue.sort()

    def _remove_from_queue(self, ticket_id: int) -> None:
        self._queue = [q for q in self._queue if q[3] != ticket_id]

    def next_ticket(self) -> int | None:
        if not self._queue:
            return None
        _, _, _, tid = self._queue.pop(0)
        self._tickets[tid]["status"] = "in_progress"
        return tid

    def close(self, ticket_id: int) -> None:
        t = self._tickets.get(ticket_id)
        if t is None:
            raise KeyError(ticket_id)
        if t["status"] == "closed":
            raise ValueError(f"Ticket {ticket_id} is already closed")
        t["status"] = "closed"
        self._remove_from_queue(ticket_id)

    def reopen(self, ticket_id: int) -> None:
        t = self._tickets.get(ticket_id)
        if t is None:
            raise KeyError(ticket_id)
        if t["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}")
        if t["status"] == "open":
            return
        t["status"] = "open"
        self._enqueue(ticket_id)
